def compute_gbs(bun, hemoglobin, gender, sbp, pulse, melena, syncope, liver_disease, cardiac_failure):
    score = 0
    # BUN (mg/dL)
    if bun < 18.2:
        score += 0
    elif bun < 22.4:
        score += 2
    elif bun <= 28.0:
        score += 3
    elif bun <= 70.0:
        score += 4
    else:
        score += 6
    # Hemoglobin (g/dL) — gender-specific
    g = gender.lower()
    if g == 'male':
        if hemoglobin >= 13:
            score += 0
        elif hemoglobin >= 12:
            score += 1
        elif hemoglobin >= 10:
            score += 3
        else:
            score += 6
    else:  # female
        if hemoglobin >= 12:
            score += 0
        elif hemoglobin >= 10:
            score += 1
        else:
            score += 6
    # Systolic BP (mmHg)
    if sbp >= 110:
        score += 0
    elif sbp >= 100:
        score += 1
    elif sbp >= 90:
        score += 2
    else:
        score += 3
    # Pulse >= 100
    if pulse >= 100:
        score += 1
    # Binary criteria
    if melena:
        score += 1
    if syncope:
        score += 1
    if liver_disease:
        score += 1
    if cardiac_failure:
        score += 1
    return score

def compute_heart_score(history, ekg, age, risk_factors_pts, troponin):
    age_pts = 0
    if age >= 65:
        age_pts = 2
    elif age >= 45:
        age_pts = 1
    return history + ekg + age_pts + risk_factors_pts + troponin

def compute_bmi(weight_kg, height_cm):
    height_m = height_cm / 100
    return round(weight_kg / (height_m * height_m), 5)

def compute_ibw(height_cm, sex):
    height_in = height_cm * 0.393701
    if sex.lower() in ('male', 'm'):
        ibw = 50 + 2.3 * (height_in - 60)
    else:
        ibw = 45.5 + 2.3 * (height_in - 60)
    return round(ibw, 5)

