def compute_abw(actual_weight_kg, ibw_kg):
    abw = ibw_kg + 0.4 * (actual_weight_kg - ibw_kg)
    return round(abw, 5)

def compute_target_weight(target_bmi, height_cm):
    height_m = height_cm / 100
    return round(target_bmi * height_m * height_m, 5)

