def compute_maintenance_fluids(weight_kg):
    if weight_kg <= 10:
        rate = 4 * weight_kg
    elif weight_kg <= 20:
        rate = 40 + 2 * (weight_kg - 10)
    else:
        rate = 60 + 1 * (weight_kg - 20)
    return round(rate, 5)

def compute_qtc_bazett(qt_ms, heart_rate):
    import math
    rr = 60.0 / heart_rate
    return round(qt_ms / math.sqrt(rr), 5)

def compute_qtc_framingham(qt_ms, heart_rate):
    rr = 60.0 / heart_rate
    return round(qt_ms + 154 * (1 - rr), 5)

def compute_qtc_fridericia(qt_ms, heart_rate):
    rr = 60.0 / heart_rate
    return round(qt_ms / (rr ** (1/3)), 5)

