def compute_fib4(age, ast, alt, platelets_per_ul):
    platelets_billions = platelets_per_ul / 1000.0
    return round((age * ast) / (platelets_billions * math.sqrt(alt)), 5)

def compute_meld_na(creatinine, bilirubin, inr, sodium, on_dialysis):
    # Clamp creatinine
    if on_dialysis:
        creatinine = 3.0
    else:
        if creatinine < 1.0:
            creatinine = 1.0
        if creatinine > 3.0:
            creatinine = 3.0
    # Clamp bilirubin and INR
    if bilirubin < 1.0:
        bilirubin = 1.0
    if inr < 1.0:
        inr = 1.0
    # Compute MELD(i)
    meld_i = 0.957 * math.log(creatinine) + 0.378 * math.log(bilirubin) + 1.120 * math.log(inr) + 0.643
    # Round to nearest tenth then multiply by 10
    meld_i_scaled = round(round(meld_i, 1) * 10)
    # Clamp sodium
    na = sodium
    if na < 125:
        na = 125
    if na > 137:
        na = 137
    # Apply sodium adjustment if MELD(i) > 11
    if meld_i_scaled > 11:
        meld_na = meld_i_scaled + 1.32 * (137 - na) - 0.033 * meld_i_scaled * (137 - na)
    else:
        meld_na = meld_i_scaled
    # Cap at 40
    if meld_na > 40:
        meld_na = 40
    return round(meld_na)

def compute_child_pugh(bilirubin, albumin, inr, ascites, encephalopathy_grade):
    # Bilirubin points
    if bilirubin < 2:
        bili_pts = 1
    elif bilirubin <= 3:
        bili_pts = 2
    else:
        bili_pts = 3
    # Albumin points
    if albumin > 3.5:
        alb_pts = 1
    elif albumin >= 2.8:
        alb_pts = 2
    else:
        alb_pts = 3
    # INR points
    if inr < 1.7:
        inr_pts = 1
    elif inr <= 2.3:
        inr_pts = 2
    else:
        inr_pts = 3
    # Ascites points
    asc = ascites.lower().strip()
    if asc == 'absent':
        asc_pts = 1
    elif asc == 'slight':
        asc_pts = 2
    else:
        asc_pts = 3
    # Encephalopathy points
    if encephalopathy_grade == 0:
        enc_pts = 1
    elif encephalopathy_grade in (1, 2):
        enc_pts = 2
    else:
        enc_pts = 3
    return bili_pts + alb_pts + inr_pts + asc_pts + enc_pts

