    return round(serum_calcium + 0.8 * (normal_albumin - patient_albumin), 5)

def compute_sofa_respiratory(pao2, fio2_percent, on_respiratory_support):
    ratio = pao2 / (fio2_percent / 100.0)
    if ratio >= 400:
        return 0
    elif ratio >= 300:
        return 1
    elif ratio >= 200:
        return 2
    elif ratio >= 100:
        return 3 if on_respiratory_support else 2
    else:
        return 4 if on_respiratory_support else 2

def compute_sofa_renal(creatinine, urine_output_per_day):
    cr_points = 0
    if creatinine < 1.2:
        cr_points = 0
    elif creatinine < 2.0:
        cr_points = 1
    elif creatinine < 3.5:
        cr_points = 2
    elif creatinine < 5.0:
        cr_points = 3
    else:
        cr_points = 4
    if urine_output_per_day < 0:
        return cr_points
    uo_points = 0
    if urine_output_per_day < 200:
        uo_points = 4
    elif urine_output_per_day < 500:
        uo_points = 3
    return max(cr_points, uo_points)

