def compute_mdrd_gfr(age, creatinine_mg_dl, is_black, is_female):
    race_coef = 1.212 if is_black else 1.0
    gender_coef = 0.742 if is_female else 1.0
    return round(175 * (creatinine_mg_dl ** -1.154) * (age ** -0.203) * race_coef * gender_coef, 5)

def compute_ckd_epi_gfr(age, creatinine_mg_dl, is_female):
    if is_female:
        A = 0.7
        B = -0.241 if creatinine_mg_dl <= 0.7 else -1.2
        gender_coef = 1.012
    else:
        A = 0.9
        B = -0.302 if creatinine_mg_dl <= 0.9 else -1.2
        gender_coef = 1.0
    return round(142 * (creatinine_mg_dl / A) ** B * (0.9938 ** age) * gender_coef, 5)

def compute_ibw(height_cm, is_female):
    height_inches = height_cm * 0.393701
    if is_female:
        ibw = 45.5 + 2.3 * (height_inches - 60)
    else:
        ibw = 50 + 2.3 * (height_inches - 60)
    return round(ibw, 5)

def compute_cg_crcl(age, weight_kg, height_cm, creatinine_mg_dl, is_female):
    height_m = height_cm / 100
    bmi = weight_kg / (height_m ** 2)
    height_inches = height_cm * 0.393701
    if is_female:
        ibw = 45.5 + 2.3 * (height_inches - 60)
        gender_coef = 0.85
    else:
        ibw = 50 + 2.3 * (height_inches - 60)
        gender_coef = 1.0
    if bmi < 18.5:
        adj_weight = weight_kg
    elif bmi < 25:
        adj_weight = min(ibw, weight_kg)
    else:
        adj_weight = ibw + 0.4 * (weight_kg - ibw)
    return round(((140 - age) * adj_weight * gender_coef) / (creatinine_mg_dl * 72), 5)

def compute_free_water_deficit(age, weight_kg, sodium_mmol_L, is_female):
    if age < 18:
        tbw = 0.6
    elif age <= 64:
        tbw = 0.5 if is_female else 0.6
    else:
        tbw = 0.45 if is_female else 0.5
    return round(tbw * weight_kg * (sodium_mmol_L / 140 - 1), 5)

def compute_edd(lmp_date, cycle_length):
    from datetime import datetime, timedelta
    lmp = datetime.strptime(lmp_date, '%m/%d/%Y')
    edd = lmp + timedelta(weeks=40) + timedelta(days=cycle_length - 28)
    return edd.strftime('%m/%d/%Y')

def compute_conception_date(lmp_date):
    from datetime import datetime, timedelta
    lmp = datetime.strptime(lmp_date, '%m/%d/%Y')
    conception = lmp + timedelta(days=14)
    return conception.strftime('%m/%d/%Y')
